namespace MMCA.Common.Azure.Tests.Notifications;

/// <summary>
/// Atom feeds of registrations as the hub returns them for <c>GET tags/{tag}/registrations</c>. The
/// two recorded feeds are verbatim hub responses from the Microsoft.Azure.NotificationHubs SDK
/// repository's MockData recordings; the edge-case feed exercises the hub's tag rules.
/// </summary>
internal static class NotificationHubFeeds
{
    private const string Namespace = "http://schemas.microsoft.com/netservices/2010/10/servicebus/connect";
    private const string FcmExtra = "<FcmV1RegistrationId>fcm-token</FcmV1RegistrationId>";
    private const string ApnsExtra = "<DeviceToken>62BCD3484834B7E2DC56733AC5509259230CC1BA82BA1AE7D06E91908A05A8FA</DeviceToken>";

    public const string RecordedAppleFeed = "<feed xmlns=\"http://www.w3.org/2005/Atom\"><title type=\"text\">Registrations</title><id>https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/tags/tag1/registrations?api-version=2017-04&amp;$top=100</id><updated>2018-11-07T00:18:23Z</updated><link rel=\"self\" href=\"https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/tags/tag1/registrations?api-version=2017-04&amp;$top=100\"/><entry a:etag=\"W/&quot;1&quot;\" xmlns:a=\"http://schemas.microsoft.com/ado/2007/08/dataservices/metadata\"><id>https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/tags/tag1/registrations/1493776553344450975-2363723502764053081-2?api-version=2017-04&amp;$top=100</id><title type=\"text\">1493776553344450975-2363723502764053081-2</title><published>2018-11-07T00:18:23Z</published><updated>2018-11-07T00:18:23Z</updated><link rel=\"self\" href=\"https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/tags/tag1/registrations/1493776553344450975-2363723502764053081-2?api-version=2017-04&amp;$top=100\"/><content type=\"application/xml\"><AppleRegistrationDescription xmlns=\"http://schemas.microsoft.com/netservices/2010/10/servicebus/connect\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"><ETag>1</ETag><ExpirationTime>9999-12-31T23:59:59.999Z</ExpirationTime><RegistrationId>1493776553344450975-2363723502764053081-2</RegistrationId><Tags>tag1</Tags><DeviceToken>62BCD3484834B7E2DC56733AC5509259230CC1BA82BA1AE7D06E91908A05A8FA</DeviceToken></AppleRegistrationDescription></content></entry><entry a:etag=\"W/&quot;1&quot;\" xmlns:a=\"http://schemas.microsoft.com/ado/2007/08/dataservices/metadata\"><id>https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/tags/tag1/registrations/3013254082390575573-1236119253991496323-3?api-version=2017-04&amp;$top=100</id><title type=\"text\">3013254082390575573-1236119253991496323-3</title><published>2018-11-07T00:18:23Z</published><updated>2018-11-07T00:18:23Z</updated><link rel=\"self\" href=\"https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/tags/tag1/registrations/3013254082390575573-1236119253991496323-3?api-version=2017-04&amp;$top=100\"/><content type=\"application/xml\"><AppleRegistrationDescription xmlns=\"http://schemas.microsoft.com/netservices/2010/10/servicebus/connect\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"><ETag>1</ETag><ExpirationTime>9999-12-31T23:59:59.999Z</ExpirationTime><RegistrationId>3013254082390575573-1236119253991496323-3</RegistrationId><Tags>tag1</Tags><DeviceToken>62BCD3484834B7E2DC56733AC5509259230CC1BA82BA1AE7D06E91908A05A8FA</DeviceToken></AppleRegistrationDescription></content></entry></feed>";

    public const string RecordedWindowsFeed = "<feed xmlns=\"http://www.w3.org/2005/Atom\"><title type=\"text\">Registrations</title><id>https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/registrations?api-version=2017-04&amp;$top=100</id><updated>2018-11-07T00:18:22Z</updated><link rel=\"self\" href=\"https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/registrations?api-version=2017-04&amp;$top=100\"/><entry a:etag=\"W/&quot;1&quot;\" xmlns:a=\"http://schemas.microsoft.com/ado/2007/08/dataservices/metadata\"><id>https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/registrations/4170287247964535769-8745470796860785881-3?api-version=2017-04&amp;$top=100</id><title type=\"text\">4170287247964535769-8745470796860785881-3</title><published>2018-11-07T00:18:22Z</published><updated>2018-11-07T00:18:22Z</updated><link rel=\"self\" href=\"https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/registrations/4170287247964535769-8745470796860785881-3?api-version=2017-04&amp;$top=100\"/><content type=\"application/xml\"><WindowsRegistrationDescription xmlns=\"http://schemas.microsoft.com/netservices/2010/10/servicebus/connect\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"><ETag>1</ETag><ExpirationTime>9999-12-31T23:59:59.9999999Z</ExpirationTime><RegistrationId>4170287247964535769-8745470796860785881-3</RegistrationId><Tags>$InstallationId:{ef4ffd64-8f20-4d6e-873c-7308b28d6a04}</Tags><ChannelUri>https://some.url/</ChannelUri></WindowsRegistrationDescription></content></entry><entry a:etag=\"W/&quot;1&quot;\" xmlns:a=\"http://schemas.microsoft.com/ado/2007/08/dataservices/metadata\"><id>https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/registrations/5763989116028704920-1411960204327425395-3?api-version=2017-04&amp;$top=100</id><title type=\"text\">5763989116028704920-1411960204327425395-3</title><published>2018-11-07T00:18:22Z</published><updated>2018-11-07T00:18:22Z</updated><link rel=\"self\" href=\"https://sdk-sample-namespace.servicebus.windows.net/sdk-sample-nh/registrations/5763989116028704920-1411960204327425395-3?api-version=2017-04&amp;$top=100\"/><content type=\"application/xml\"><WindowsTemplateRegistrationDescription xmlns=\"http://schemas.microsoft.com/netservices/2010/10/servicebus/connect\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"><ETag>1</ETag><ExpirationTime>9999-12-31T23:59:59.9999999Z</ExpirationTime><RegistrationId>5763989116028704920-1411960204327425395-3</RegistrationId><Tags>$InstallationId:{ef4ffd64-8f20-4d6e-873c-7308b28d6a04},Template Name</Tags><ChannelUri>https://some.url/</ChannelUri><BodyTemplate><![CDATA[{\"aps\":{\"alert\":\"alert!\"}}]]></BodyTemplate><WnsHeaders><WnsHeader><Header>X-WNS-Type</Header><Value>wns/toast</Value></WnsHeader></WnsHeaders><TemplateName>Template Name</TemplateName></WindowsTemplateRegistrationDescription></content></entry></feed>";

    /// <summary>
    /// Nine registrations: plain FCM v1, an APNs one whose owner tag repeats in another case, two
    /// installation system tags, a 121-character tag, a 120-character tag beside a user system tag,
    /// no Tags element, an empty tag, and two template registrations.
    /// </summary>
    public static string EdgeCaseFeed { get; } = Feed(
        Entry("FcmV1RegistrationDescription", "<Tags>$InstallationId:{3f0c2f9c-1e8b-4b6c-9d3a-5e7f0a1b2c3d},user:42</Tags>", FcmExtra),
        Entry("AppleRegistrationDescription", "<Tags>user:42,$installationid:{SECOND},USER:42</Tags>", ApnsExtra),
        Entry("FcmV1RegistrationDescription", "<Tags>user:42,$InstallationId:{a},$InstallationId:{b}</Tags>", FcmExtra),
        Entry("FcmV1RegistrationDescription", "<Tags>user:42," + new string('x', 121) + "</Tags>", FcmExtra),
        Entry("FcmV1RegistrationDescription", "<Tags>user:42," + new string('x', 120) + ",$UserId:{u@x.com}</Tags>", FcmExtra),
        Entry("FcmV1RegistrationDescription", string.Empty, FcmExtra),
        Entry("FcmV1RegistrationDescription", "<Tags>user:42,,x</Tags>", FcmExtra),
        Entry("AppleTemplateRegistrationDescription", "<Tags>$InstallationId:{c},user:42,tmpl</Tags>", ApnsExtra + "<BodyTemplate><![CDATA[{\"aps\":{}}]]></BodyTemplate><TemplateName>tmpl</TemplateName>"),
        Entry("FcmV1TemplateRegistrationDescription", "<Tags>$InstallationId:{d=e},user:42</Tags>", FcmExtra + "<BodyTemplate><![CDATA[{}]]></BodyTemplate><TemplateName>t</TemplateName>"));

    public static string Feed(params string[] entries) =>
        "<feed xmlns=\"http://www.w3.org/2005/Atom\"><title type=\"text\">Registrations</title><id>https://mmca-ns.servicebus.windows.net/mmca-hub/tags/user:42/registrations?api-version=2020-06</id><updated>2026-11-24T00:00:00Z</updated><link rel=\"self\" href=\"https://mmca-ns.servicebus.windows.net/mmca-hub/tags/user:42/registrations?api-version=2020-06\"/>"
        + string.Concat(entries) + "</feed>";

    private static string Entry(string element, string tagsElement, string extra) =>
        "<entry a:etag=\"W/&quot;1&quot;\" xmlns:a=\"http://schemas.microsoft.com/ado/2007/08/dataservices/metadata\"><id>https://mmca-ns.servicebus.windows.net/mmca-hub/registrations/1?api-version=2020-06</id><title type=\"text\">1</title><published>2026-11-24T00:00:00Z</published><updated>2026-11-24T00:00:00Z</updated><link rel=\"self\" href=\"https://mmca-ns.servicebus.windows.net/mmca-hub/registrations/1?api-version=2020-06\"/>"
        + $"<content type=\"application/xml\"><{element} xmlns=\"{Namespace}\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"><ETag>1</ETag><ExpirationTime>9999-12-31T23:59:59.9999999Z</ExpirationTime><RegistrationId>1</RegistrationId>{tagsElement}{extra}</{element}></content></entry>";
}
